@Test
public void testProcessLogs() throws IOException, IvoryException, InterruptedException {
    Path instanceLogPath = new Path("/projects/ivory/staging/ivory/workflows/process/" + "sample" + "/logs/job-2010-01-01-01-00/000");
    Path instanceLogPath1 = new Path("/projects/ivory/staging/ivory/workflows/process/" + "sample" + "/logs/job-2010-01-01-01-00/001");
    Path instanceLogPath2 = new Path("/projects/ivory/staging/ivory/workflows/process/" + "sample" + "/logs/job-2010-01-01-02-00/001");
    Path instanceLogPath3 = new Path("/projects/ivory/staging/ivory/workflows/process/" + "sample2" + "/logs/job-2010-01-01-01-00/000");
    Path instanceLogPath4 = new Path("/projects/ivory/staging/ivory/workflows/process/" + "sample" + "/logs/latedata/2010-01-01-01-00");
    fs.mkdirs(instanceLogPath);
    fs.mkdirs(instanceLogPath1);
    fs.mkdirs(instanceLogPath2);
    fs.mkdirs(instanceLogPath3);
    fs.mkdirs(instanceLogPath4);
    // fs.setTimes wont work on dirs
    fs.createNewFile(new Path(instanceLogPath, "oozie.log"));
    fs.createNewFile(new Path(instanceLogPath, "pigAction_SUCCEEDED.log"));
    Thread.sleep(61000);
    AbstractCleanupHandler processCleanupHandler = new ProcessCleanupHandler();
    processCleanupHandler.cleanup();
    Assert.assertFalse(fs.exists(instanceLogPath));
    Assert.assertFalse(fs.exists(instanceLogPath1));
    Assert.assertFalse(fs.exists(instanceLogPath2));
    Assert.assertTrue(fs.exists(instanceLogPath3));
}

