@Test
public void testLogMover() throws Exception {
    CurrentUser.authenticate(System.getProperty("user.name"));
    OozieWorkflowEngine engine = new OozieWorkflowEngine();
    engine.schedule(testProcess);
    OozieClient client = new OozieClient(ClusterHelper.getOozieUrl(testCluster.getCluster()));
    List<WorkflowJob> jobs;
    while (true) {
        jobs = client.getJobsInfo(OozieClient.FILTER_NAME + "=" + "IVORY_PROCESS_DEFAULT_" + processName);
        if (jobs.size() > 0) {
            break;
        } else {
            Thread.sleep(100);
        }
    }
    WorkflowJob job = jobs.get(0);
    while (true) {
        if (!(job.getStatus() == WorkflowJob.Status.RUNNING || job.getStatus() == WorkflowJob.Status.PREP)) {
            break;
        } else {
            Thread.sleep(100);
            job = client.getJobInfo(job.getId());
        }
    }
    Path oozieLogPath = new Path(getLogPath(), "job-2010-01-01-01-00/000/oozie.log");
    Assert.assertTrue(fs.exists(oozieLogPath));
    testLogMoverWithNextRunId(job.getId());
}

